{
  "id": "rw-balancer-upscale",
  "family": "fixed-point",
  "split": "realworld",
  "issue_report": "The swap wrapper `BalancerSwap.onSwap` (a port of the regular-swap path of Balancer V2's BaseGeneralPool, as deployed for the osETH/WETH Composable Stable Pool 0xDACf5Fa19b1f720111609043ac67A9818262850c on Ethereum) lets a batch of small given-out swaps drain the pool. In transaction 0x6ed07db1a9fe5c0794d44cd36081d6a6df103fab868cdd75d581e3bd23bc9742 (2025-11-03) the pool held 67,000 wei of WETH and 67,000 wei of osETH (scaling factor 1058132408689971699, fee 0.01%), and 30 rounds of three given-out swaps (osETH out down to 18 wei, then 17 wei of osETH out, then WETH out paid with osETH) took its invariant from 137,893 to 2,445. A request for 17 wei of osETH is worth 17.988 of the pool's 18-decimal units, but the pool math is asked to price 17 units: the first such swap was charged 625,492 wei of WETH, while 18 units cost 1,041,412. With the constant-product math of the specification, four rounds of this shape take the pool's WETH from 67,000 to 4,193 wei.",
  "definitions_under_repair": [
    "BalancerSwap.onSwap"
  ],
  "namespace": "BalancerSwap",
  "candidate": "candidate/Solution.lean",
  "locked_files": [
    "spec/BalancerSwap/Spec.lean",
    "spec/BalancerSwap/Challenge.lean"
  ],
  "requirements": [
    {
      "id": "REQ-GIVEN-IN-SUCCEEDS",
      "theorem": "BalancerSwap.req_given_in_succeeds",
      "statement": "GivenInSucceeds onSwap",
      "text": "REQ-GIVEN-IN-SUCCEEDS: a given-in swap between two tokens of the pool goes through, for any well-behaved math, when the scaling factor of the token out is positive and the fee is below 100%."
    },
    {
      "id": "REQ-GIVEN-OUT-SUCCEEDS",
      "theorem": "BalancerSwap.req_given_out_succeeds",
      "statement": "GivenOutSucceeds onSwap",
      "text": "REQ-GIVEN-OUT-SUCCEEDS: a given-out swap between two tokens of the pool goes through, for any well-behaved math, when the exact amount out rounded up is below the pool's balance of that token (both in 18-decimal units), the scaling factor of the token in is positive and the fee is below 100%."
    },
    {
      "id": "REQ-GIVEN-IN-PAYS-AT-MOST",
      "theorem": "BalancerSwap.req_given_in_pays_at_most",
      "statement": "GivenInPaysAtMost onSwap",
      "text": "REQ-GIVEN-IN-PAYS-AT-MOST: in a given-in swap the trader receives at most what the math prices the exact amount in, net of the fee, rounded down: `y * rate_out / 1e18` is at most `outGivenIn` of that amount. Rounding never pays out more than the trader paid for."
    },
    {
      "id": "REQ-GIVEN-IN-PAYS-AT-LEAST",
      "theorem": "BalancerSwap.req_given_in_pays_at_least",
      "statement": "GivenInPaysAtLeast onSwap",
      "text": "REQ-GIVEN-IN-PAYS-AT-LEAST: and it receives at least what the math prices one raw unit less than the net amount in, less one raw unit out: the rounding costs the trader at most one unit on each side."
    },
    {
      "id": "REQ-GIVEN-OUT-CHARGES-AT-LEAST",
      "theorem": "BalancerSwap.req_given_out_charges_at_least",
      "statement": "GivenOutChargesAtLeast onSwap",
      "text": "REQ-GIVEN-OUT-CHARGES-AT-LEAST: in a given-out swap the trader is charged, after the fee, at least what the math prices the exact amount out rounded up to a whole 18-decimal unit: `c * (1 - fee) * rate_in / 1e18` is at least `outPrice`. Rounding never lets the trader take more than it pays for."
    },
    {
      "id": "REQ-GIVEN-OUT-CHARGES-AT-MOST",
      "theorem": "BalancerSwap.req_given_out_charges_at_most",
      "statement": "GivenOutChargesAtMost onSwap",
      "text": "REQ-GIVEN-OUT-CHARGES-AT-MOST: and one raw unit less than the charge, after the fee, is below that price plus one raw unit of the token in: the rounding costs the trader at most one unit for the conversion back to raw units and one for the fee."
    },
    {
      "id": "REQ-SWAP-KEEPS-VALUE",
      "theorem": "BalancerSwap.req_swap_keeps_value",
      "statement": "SwapKeepsValue onSwap",
      "text": "REQ-SWAP-KEEPS-VALUE: for any well-behaved math, a swap that goes through never lowers the pool's value as the pool measures it (`value`)."
    },
    {
      "id": "REQ-BATCH-KEEPS-VALUE",
      "theorem": "BalancerSwap.req_batch_keeps_value",
      "statement": "BatchKeepsValue onSwap",
      "text": "REQ-BATCH-KEEPS-VALUE: for any well-behaved math, any pool and any batch of swaps of either kind, a batch that goes through never lowers the pool's value as the pool measures it. The rounding of one swap cannot be repeated inside a batch to drain the pool."
    }
  ],
  "rules": {
    "edit_only": "candidate/Solution.lean (and optionally candidate/Lib/**); spec/, app/ and the Lake files are locked and checked byte for byte",
    "allowed_imports": [
      "BalancerSwap.Spec",
      "Init.*",
      "Std.*",
      "ProofForgeFin.*"
    ],
    "forbidden": "sorry, axiom, opaque, implemented_by, extern, unsafe, @[export], macro, elab, syntax, initialize, #eval, run_cmd, native_decide, set_option, @[csimp], simprocs and other elaboration-time code",
    "permitted_axioms": [
      "propext",
      "Quot.sound",
      "Classical.choice"
    ],
    "statements": "every required theorem must have exactly the locked statement in Challenge.lean"
  },
  "library": "ProofForgeFin is vendored in this workspace: `import ProofForgeFin` or one module; search_library finds its theorems and tactics."
}

